# Kaggle script kernel: residual stale-float (norm eps).
import base64, subprocess, sys
payload = {'norm_eps_stale_min.py': '', 'layer_norm_eps_stale2.py': ''}
for n, b in payload.items():
    open(n, 'wb').write(base64.b64decode(b))
for spec in [["torch==2.14.0", "--index-url", "https://download.pytorch.org/whl/cpu"], ["--pre", "--upgrade", "torch", "--index-url", "https://download.pytorch.org/whl/nightly/cpu"]]:
    subprocess.run(["pip", "-q", "install", *spec])
    for n in payload:
        print('=====', n, flush=True)
        subprocess.run([sys.executable, n])
print("JOB DONE", flush=True)
